import { describe, it, expect } from 'vitest';
import { renderSummary } from './report.js';
import { GateResult } from './schema.js';

describe('renderSummary', () => {
  it('returns PASS 7/7 when all checks pass', () => {
    const result: GateResult = {
      verdict: 'PASS',
      tier: 'minimal',
      findings: [],
      gateSection: '# Responsible AI Gate\n\nAll checks answered.'
    };
    expect(renderSummary(result)).toBe('PASS 7/7');
  });

  it('returns WARN 7/7 when warnings only (no block findings)', () => {
    const result: GateResult = {
      verdict: 'WARN',
      tier: 'high',
      findings: [
        {
          checkId: 'evaluation',
          severity: 'warn',
          message: 'Evaluation plan could be more detailed',
          source: 'validator'
        }
      ],
      gateSection: '# Responsible AI Gate\n\nSome warnings.'
    };
    expect(renderSummary(result)).toBe('WARN 7/7');
  });

  it('returns BLOCK 0/7: structure when gate section is null', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [],
      gateSection: null
    };
    expect(renderSummary(result)).toBe('BLOCK 0/7: structure');
  });

  it('returns BLOCK X/7: id1, id2 when some checks fail', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'evaluation',
          severity: 'block',
          message: 'Evaluation plan missing',
          source: 'validator'
        },
        {
          checkId: 'transparency',
          severity: 'block',
          message: 'Transparency requirements unclear',
          source: 'validator'
        }
      ],
      gateSection: '# Responsible AI Gate\n\nSome items missing.'
    };
    expect(renderSummary(result)).toBe('BLOCK 5/7: evaluation, transparency');
  });

  it('lists failed check IDs in GATE_CHECKS order, not alphabetical', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'transparency',
          severity: 'block',
          message: 'Missing',
          source: 'validator'
        },
        {
          checkId: 'risk-tier',
          severity: 'block',
          message: 'Missing',
          source: 'validator'
        }
      ],
      gateSection: '# Gate\n\nMissing.'
    };
    // Should be "risk-tier, transparency" (GATE_CHECKS order) not "risk-tier, transparency"
    expect(renderSummary(result)).toBe('BLOCK 5/7: risk-tier, transparency');
  });

  it('includes each check ID only once even with multiple findings', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'evaluation',
          severity: 'block',
          message: 'Missing thresholds',
          source: 'validator'
        },
        {
          checkId: 'evaluation',
          severity: 'warn',
          message: 'Could be more comprehensive',
          source: 'agent'
        }
      ],
      gateSection: '# Gate\n\nMissing.'
    };
    expect(renderSummary(result)).toBe('BLOCK 6/7: evaluation');
  });

  it('counts answered correctly with mixed block and warn findings', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        {
          checkId: 'oversight',
          severity: 'block',
          message: 'Missing oversight details',
          source: 'validator'
        },
        {
          checkId: 'data-privacy',
          severity: 'warn',
          message: 'Could be more detailed',
          source: 'validator'
        },
        {
          checkId: 'bias',
          severity: 'block',
          message: 'Missing bias analysis',
          source: 'validator'
        }
      ],
      gateSection: '# Gate\n\nPartial.'
    };
    // Answered: all except oversight and bias (2 blocks) = 5
    expect(renderSummary(result)).toBe('BLOCK 5/7: oversight, bias');
  });

  it('handles all checks failing', () => {
    const result: GateResult = {
      verdict: 'BLOCK',
      tier: null,
      findings: [
        { checkId: 'risk-tier', severity: 'block', message: 'Missing', source: 'validator' },
        { checkId: 'data-privacy', severity: 'block', message: 'Missing', source: 'validator' },
        { checkId: 'oversight', severity: 'block', message: 'Missing', source: 'validator' },
        { checkId: 'evaluation', severity: 'block', message: 'Missing', source: 'validator' },
        { checkId: 'bias', severity: 'block', message: 'Missing', source: 'validator' },
        { checkId: 'monitoring', severity: 'block', message: 'Missing', source: 'validator' },
        { checkId: 'transparency', severity: 'block', message: 'Missing', source: 'validator' }
      ],
      gateSection: '# Gate\n\nAll missing.'
    };
    expect(renderSummary(result)).toBe(
      'BLOCK 0/7: risk-tier, data-privacy, oversight, evaluation, bias, monitoring, transparency'
    );
  });
});

