import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { execSync } from 'node:child_process';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PROJECT_ROOT = path.resolve(__dirname, '../..');
const TEMP_DIR = path.resolve(PROJECT_ROOT, '.test-specs');

// Helper to run frai-gate command
function runFraiGate(args: string[]): { stdout: string; stderr: string; code: number } {
  try {
    const stdout = execSync(`node dist/cli.js ${args.join(' ')}`, {
      cwd: PROJECT_ROOT,
      encoding: 'utf8'
    });
    return { stdout, stderr: '', code: 0 };
  } catch (error: unknown) {
    if (error instanceof Error && 'status' in error && 'stderr' in error && 'stdout' in error) {
      return {
        stdout: (error.stdout as string) || '',
        stderr: (error.stderr as string) || '',
        code: error.status as number
      };
    }
    throw error;
  }
}

describe('CLI: --summary flag', () => {
  beforeAll(async () => {
    // Create temp directory for test specs
    await fs.mkdir(TEMP_DIR, { recursive: true });
  });

  afterAll(async () => {
    // Clean up test specs
    await fs.rm(TEMP_DIR, { recursive: true, force: true });
  });

  it('outputs one-line summary when --summary flag is used on passing spec', async () => {
    const specPath = path.join(TEMP_DIR, 'test-pass.md');
    const spec = `# Test Spec - All Checks Pass

## Responsible AI Gate

### Risk Tier
Minimal risk - this is a demonstration feature.

### Data & Privacy
No sensitive data handling involved.

### Human Oversight
Manual review is performed before deployment.

### Evaluation Plan
Standard QA testing with 3 test scenarios.

### Bias & Fairness
Standard bias review process applied.

### Monitoring & Rollback
Monitoring via standard observability, rollback is manual.

### Transparency & Incidents
Feature documented in release notes.
`;
    await fs.writeFile(specPath, spec, 'utf8');

    const result = runFraiGate(['check', specPath, '--summary']);
    expect(result.code).toBe(0);
    expect(result.stdout.trim()).toBe('PASS 7/7');
  });

  it('outputs summary with failed check IDs when --summary flag is used on failing spec', async () => {
    const specPath = path.join(TEMP_DIR, 'test-block.md');
    const spec = `# Test Spec - With Block Findings

## Responsible AI Gate

### Risk Tier
[NEEDS HUMAN INPUT: risk tier assessment]

### Data & Privacy
No sensitive data handling.

### Human Oversight
[NEEDS HUMAN INPUT: oversight approach]

### Evaluation Plan
Standard testing.

### Bias & Fairness
Standard bias review.

### Monitoring & Rollback
Monitoring in place.

### Transparency & Incidents
Documented in notes.
`;
    await fs.writeFile(specPath, spec, 'utf8');

    const result = runFraiGate(['check', specPath, '--summary']);
    expect(result.code).toBe(1);
    // Should show block with failed check IDs
    expect(result.stdout.trim()).toMatch(/^BLOCK \d\/7: /);
    expect(result.stdout.trim()).toContain('risk-tier');
    expect(result.stdout.trim()).toContain('oversight');
  });

  it('outputs BLOCK 0/7: structure when gate section is missing', async () => {
    const specPath = path.join(TEMP_DIR, 'test-no-gate.md');
    const spec = `# Test Spec - No Gate Section

This spec has no Responsible AI Gate section at all.

Just regular content here.
`;
    await fs.writeFile(specPath, spec, 'utf8');

    const result = runFraiGate(['check', specPath, '--summary']);
    expect(result.code).toBe(1);
    expect(result.stdout.trim()).toBe('BLOCK 0/7: structure');
  });

  it('preserves exit code 0 for passing spec with --summary', async () => {
    const specPath = path.join(TEMP_DIR, 'test-pass-exit.md');
    const spec = `# Test Spec - All Checks Pass

## Responsible AI Gate

### Risk Tier
Minimal risk.

### Data & Privacy
No sensitive data.

### Human Oversight
Manual review.

### Evaluation Plan
Standard QA testing.

### Bias & Fairness
Standard review.

### Monitoring & Rollback
Monitoring in place.

### Transparency & Incidents
Documented.
`;
    await fs.writeFile(specPath, spec, 'utf8');

    const result = runFraiGate(['check', specPath, '--summary']);
    expect(result.code).toBe(0);
  });

  it('preserves exit code 1 for failing spec with --summary', async () => {
    const specPath = path.join(TEMP_DIR, 'test-fail-exit.md');
    const spec = `# Test Spec - Missing Gate

No gate section provided.
`;
    await fs.writeFile(specPath, spec, 'utf8');

    const result = runFraiGate(['check', specPath, '--summary']);
    expect(result.code).toBe(1);
  });

  it('gives priority to --json over --summary flag', async () => {
    const specPath = path.join(TEMP_DIR, 'test-priority.md');
    const spec = `# Test Spec

## Responsible AI Gate

### Risk Tier
Minimal.

### Data & Privacy
No data.

### Human Oversight
Manual.

### Evaluation Plan
QA.

### Bias & Fairness
Review.

### Monitoring & Rollback
Monitoring.

### Transparency & Incidents
Documented.
`;
    await fs.writeFile(specPath, spec, 'utf8');

    const result = runFraiGate(['check', specPath, '--summary', '--json']);
    expect(result.code).toBe(0);
    // Should output JSON, not summary
    expect(result.stdout.trim()).toContain('"verdict"');
    expect(result.stdout.trim()).toContain('"findings"');
    expect(result.stdout.trim()).not.toBe('PASS 7/7');
  });

  it('documents --summary flag in help text', () => {
    const result = runFraiGate(['check', '--help']);
    expect(result.stdout).toContain('--summary');
    expect(result.stdout).toContain('one-line summary');
  });
});

